113	/** Feeds the trial-expiry job; cross-tenant by design, it sweeps every org. */
114	export async function listTrialsEndingBefore(
115	  before: IsoTimestamp,
116	): Promise<readonly Subscription[]> {
117	  const rows = getDb()
118	    .select()
119	    .from(subscriptions)
120	    .where(
121	      and(
122	        eq(subscriptions.status, "trialing"),
123	        isNotNull(subscriptions.currentPeriodEnd),
124	        lte(subscriptions.currentPeriodEnd, before),
125	        ne(subscriptions.plan, "free"),
126	      ),
127	    )
128	    .all();
129	
130	  return rows.map(toSubscription);
