 * The rollup job's work list: the oldest measurements first. Closed
 * organizations are excluded so every sweep built on this list — digest,
 * overdue reminders, usage rollup, retention cleanup — skips them entirely.
 */
export async function listOrgIdsForRollup(
  limit: number,
): Promise<readonly OrgId[]> {
  const rows = getDb()
    .select({ orgId: organizationUsage.orgId })
    .from(organizationUsage)
    .innerJoin(organizations, eq(organizations.id, organizationUsage.orgId))
    .where(isNull(organizations.archivedAt))
    .orderBy(organizationUsage.measuredAt)
    .limit(Math.max(1, limit))
    .all();

  return rows.map((row) => brandId<OrgId>(row.orgId));
}

